local Ps=Ns/math.max(1e-9,Os.need/J.Bal.StageUnit)
local Qs=I.lerp({{0.5,0.02},{0.6,0.1},{0.7,0.3},{0.85,0.62},{1.0,0.9},{1.3,0.98}},Ps)
local Rs=z.stages[QA[303]..Ms]
