return Qs
end
local Ss,Ts=0,0
for Us,Vs in ipairs(Rs.res)do
local Ws,Xs=tonumber(Vs[1]),tonumber(Vs[2])
if Ws and Xs and Ws>0 then
local Ys=math.exp(-math.abs(math.log(Ps/Ws))*4)
if Xs==1 and Ws<=Ps then
Ys=1
end
if Xs==0 and Ws>=Ps then
Ys=1
end
Ss=Ss+Ys
Ts=Ts+Ys*Xs
end
end
return(Ts+Qs*2)/(Ss+2)
