function V.fightPlan(ot,pt,qt,rt)
local tt=math.max(0,ot.needWins-rt)
local ut,vt=J.P.WorldGate(ot.evo,qt,J.Maps.Live)
if tt<=0 and not ut then
return 0,nil
end
local wt
local xt,yt=0,0
for zt=1,x.MAX_STAGE do
if J.Maps.WorldOfStage(zt)>(y.worlds and x.MAX_WORLD or 1)then
break
end
local Bt=V.pwin(zt,pt)
if Bt<y.minWin then
break
end
if zt>qt then
xt=xt+V.clearMin(zt)/Bt
yt=yt+V.winsPer(zt)
end
local Ct=math.max(0,tt-yt)
local Dt=math.max(1e-9,V.winsPer(zt))
local Et=math.ceil(Ct/Dt)
local Ft=xt+Et*V.replayMin(zt)/Bt
if ut and math.max(qt,zt)<(vt or 0)then
Ft=x.BIG
end
if not wt or Ft<wt.mins then
wt={mins=Ft,t=zt,reps=Et}
end
end
if not wt then
return x.BIG,nil
end
return math.min(wt.mins,x.BIG),wt
end
