function e.loop()
local Mv=0
local Nv,Ov
while e.alive do
task.wait(0.4)
if not y.master then
e.now={icon=QA[716],title=QA[717],text=QA[718],sub=QA[140]}
continue
end
if e.yielding()then
e.now={icon=QA[113],title=QA[719],text=QA[720],sub=string.format(QA[721],math.ceil(e.yieldUntil-os.clock()))}
continue
end
if not K.alive()then
e.now={icon=QA[722],title=QA[723],text=QA[140],sub=QA[140]}
continue
end
if y.raid and z.move.ok~=nil and db.wanted()then
local Pv,Qv=pcall(db.step)
if not Pv then
e.log(1,QA[177],QA[724]..tostring(Qv))
task.wait(2)
end
if not Pv or Qv~=false then
continue
end
elseif db.run and not db.inRaid()then
pcall(db.finish)
end
if cb.awayAt and y.farmMode~=QA[487]then
if not cb.inRun()then
cb.awayAt=nil
else
local Rv=x.DEPTHS_AWAY-(os.clock()-cb.awayAt)
if Rv>0 then
e.now={icon=QA[11],title=QA[725]..math.ceil(Rv)..QA[281],text=QA[726],sub=QA[140]}
continue
end
cb.awayAt=nil
pcall(function()
J.Net.Event(QA[204]):FireServer(QA[520])
end)
e.log(1,QA[488],QA[727]..tostring(y.farmMode)..QA[356])
pcall(cb.finish,QA[728])
continue
end
end
if y.farmMode==QA[487]and z.move.ok~=nil then
local Sv,Tv=pcall(cb.step)
if not Sv then
e.log(1,QA[177],QA[729]..tostring(Tv))
task.wait(2)
end
continue
end
local Uv=J.busyElsewhere()
if Uv then
e.now={icon=QA[722],title=QA[730]..Uv,text=QA[731],sub=QA[140]}
continue
end
if z.move.ok==nil then
K.test()
continue
end
local Vv=J.winReadyList()
if#Vv>0 and y.fight and z.move.ok and N.allowed(Vv[1])and not cb.inRun()then
local Wv,Xv=N.claim(Vv[1])
if Wv then
e.note(QA[44],QA[732]..Vv[1]..QA[733]..I.fmt(Xv)..QA[734])
else
N.cool[Vv[1]]=os.clock()+120
end
continue
end
if e.forceFight and z.move.ok then
local Yv=e.forceFight
e.forceFight=nil
N.run(Yv)
continue
end
local Zv=J.EC:Active()
if Zv and Zv<=x.MAX_STAGE and y.fight and z.move.ok then
N.run(Zv)
continue
end
if os.clock()>=Mv or not Ov then
Nv=V.compute()
Ov=V.choose(Nv)
Mv=os.clock()+2
end
if not Ov then
e.now={icon=QA[722],title=QA[735],text=QA[736],sub=QA[140]}
continue
end
if Ov.kind==QA[706]then
U.run(Nv.st)
Ov=nil
elseif Ov.kind==QA[386]then
if z.move.ok then
N.run(Ov.s)
else
e.now={icon=QA[259],title=QA[737],text=QA[738],sub=QA[140]}
end
Ov=nil
elseif Ov.kind==QA[479]then
local _v=Ov.pad
if M.onPad(_v)then
M.measure(_v)
e.now={icon=QA[38],title=QA[739].._v.name..QA[300].._v.mult,text=QA[740]..I.lvl(Nv.st)..QA[372]..I.fmt(M.lastRate or 0)..QA[741],sub=V.whyLine or QA[140]}
elseif not M.ensure(_v)then
Ov=nil
task.wait(2)
end
end
end
end
